    const v_info: u8[] = unhex(table_info[i]);
    const v_n: i32 = table_n[i];
    const u: Unwrap = new Unwrap();
    const holds: boolean = (bytesEq(u.get(plain_hkdfSha256Secret(v_salt, v_ikm, v_info, v_n)), u.get(hkdfExpandSha256(hkdfExtractSha256(v_salt, v_ikm), v_info, v_n))) && bytesEq(u.get(plain_hkdfSha384Secret(v_salt, v_ikm, v_info, v_n)), u.get(hkdfExpandSha384(hkdfExtractSha384(v_salt, v_ikm), v_info, v_n))));
