export const main = (): i32 => {
  const t: Suite = new Suite("rfc5869-hkdf-sha256");
  let ran: string = "";
  ran = `${ran}${clause_A_1_PRK(t) ? "1" : "0"}`;
  ran = `${ran}${clause_A_1_OKM(t) ? "1" : "0"}`;
  ran = `${ran}${clause_A_2_PRK(t) ? "1" : "0"}`;
  ran = `${ran}${clause_A_2_OKM(t) ? "1" : "0"}`;
  ran = `${ran}${clause_A_3_PRK(t) ? "1" : "0"}`;
  ran = `${ran}${clause_A_3_OKM(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_EXTRACT_IS_HMAC(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_EMPTY_SALT(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_PRK_LEN(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_EXPAND_LENGTH(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_T1_T2(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_PREFIX(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_EXTRACT_IS_HMAC_384(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_EMPTY_SALT_384(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_T1_T2_384(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_EXPAND_LENGTH_384(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_SECRET_EXTRACT(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_SECRET_EXPAND_256(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_SECRET_EXPAND_384(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_SECRET_HKDF(t) ? "1" : "0"}`;
  const code: i32 = t.done();
  const nonce: string = toI32(process.argv.length) > 1 ? process.argv[1] : "-";
  console.log(`vector-done ${nonce} ${ran}`);
  return code;
};
